270	interface ResultsViewerProps {
271	  taskId?: string | null;
272	  artifacts?: readonly ArtifactProjection[];
273	  activities?: readonly ActivityProjection[];
274	}
275	
276	export default function ResultsViewer({
277	  taskId: taskIdOverride,
278	  artifacts: artifactOverride,
279	  activities: activityOverride,
280	}: ResultsViewerProps = {}) {
281	  const task = useAgentStore(selectActiveTask);
282	  const activeArtifacts = useAgentStore(selectActiveArtifacts);
283	  const activeActivities = useAgentStore(selectActiveActivities);
284	  const taskId = taskIdOverride ?? task?.summary.task_id ?? null;
285	  const artifacts = artifactOverride ?? activeArtifacts;
286	  const activities = activityOverride ?? activeActivities;
287	  const latestRunId = task?.runOrder[task.runOrder.length - 1];
288	  const latestRun =
289	    latestRunId === undefined ? undefined : task?.runsById[latestRunId];
290	  const buildResult = latestRun?.summary?.build_result;
291	  // The empty-state title and the per-artifact preview message describe the
292	  // LATEST run's outcome. The empty state is only rendered when NO artifacts
293	  // exist (ownership is trivially satisfied), so it may use the plain latest
294	  // NO_DATA message. The preview message, however, renders over whatever
295	  // artifacts are listed — the artifact list is reset at each run_manifest
296	  // and accumulates that cycle's artifacts, so when the latest NO_DATA run
297	  // produced none (available_artifact_roles: [] — e.g. acquisition found
298	  // nothing), the visible artifacts belong to an EARLIER run and must not
299	  // carry this run's NO_DATA message.
300	  const noDataMessage =
301	    buildResult?.status === "no_data"
302	      ? latestRun?.summary?.user_message ?? "无数据"
303	      : undefined;
304	  const noDataOwnsArtifacts =
305	    buildResult?.status === "no_data" &&
306	    buildResult != null &&
307	    buildResult.available_artifact_roles.length > 0 &&
308	    artifacts.length > 0;
309	  const previewNoDataMessage = noDataOwnsArtifacts
310	    ? noDataMessage
311	    : undefined;
312	  const noDataContext =
313	    buildResult?.status === "no_data" &&
314	    (buildResult.user_summary !== "" ||
315	      buildResult.recommended_next_action !== "")
316	      ? {
317	          userSummary:
318	            buildResult.user_summary === ""
319	              ? "无数据"
320	              : buildResult.user_summary,
321	          recommendedNextAction: buildResult.recommended_next_action,
322	        }
323	      : undefined;
324	  // The banner describes the LATEST run's outcome, so it may only render
325	  // over that run's OWN artifacts (see noDataOwnsArtifacts above).
326	  const showNoDataBanner =
327	    noDataContext !== undefined && noDataOwnsArtifacts;
328	
329	  if (taskId === null) {
330	    return (
331	      <Empty className="min-h-48">
332	        <EmptyHeader>
333	          <EmptyTitle>选择任务查看结果</EmptyTitle>
334	          <EmptyDescription>选择一个任务后，这里会显示其产物和来源。</EmptyDescription>
335	        </EmptyHeader>
336	      </Empty>
337	    );
338	  }
339	
340	  const isActive = artifactOverride === undefined &&
341	    task !== undefined &&
342	    isActiveStatus(task.summary.status);
343	  if (artifacts.length === 0 && isActive) {
344	    return (
345	      <div className="flex min-w-0 items-center justify-center gap-2 py-12 text-sm text-muted-foreground">
346	        <Spinner />
347	        处理中...
348	      </div>
349	    );
350	  }
351	  if (artifacts.length === 0) {
352	    return (
353	      <Empty className="min-h-48">
354	        <EmptyHeader>
355	          <EmptyTitle>{noDataMessage ?? "暂无结果"}</EmptyTitle>
356	          <EmptyDescription>该任务尚未生成可下载的产物。</EmptyDescription>
357	        </EmptyHeader>
358	      </Empty>
359	    );
360	  }
361	
362	  const sourceData = parseSourceManifest(activities);
363	  return (
364	    <div className="flex h-full min-h-0 min-w-0 flex-col gap-4">
365	      {sourceData.length > 0 && (
366	        <Accordion>
367	          <AccordionItem value="source-manifest">
368	            <AccordionTrigger>
369	              <DatabaseIcon aria-hidden="true" />
370	              数据来源
371	            </AccordionTrigger>
372	            <AccordionContent>
373	              <div className="flex min-w-0 flex-col gap-2">
374	                {sourceData.map((entry) => (
375	                  <Card key={entry.id} size="sm" className="min-w-0">
376	                    <CardHeader>
377	                      <CardTitle className="truncate text-xs font-mono" title={entry.tool}>{entry.tool}</CardTitle>
378	                      <CardDescription>{entry.summary}</CardDescription>
379	                    </CardHeader>
380	                    <CardContent>
381	                      <pre className="max-w-full whitespace-pre-wrap break-words font-mono text-[0.625rem] leading-relaxed text-muted-foreground">{entry.details}</pre>
382	                    </CardContent>
383	                  </Card>
384	                ))}
385	              </div>
