 92	function terminalizeRunningFixtureStages(
 93	  task: TaskProjection,
 94	  status: "failed" | "cancelled",
 95	  timestamp: string,
 96	  error: string | null,
 97	): TaskProjection {
 98	  if (task.summary.mode !== "fixture") return task;
 99	  const stages = { ...task.stages };
100	  let changed = false;
101	  for (const stage of Object.keys(stages) as StageName[]) {
102	    const projection = stages[stage];
103	    if (projection?.status !== "running") continue;
104	    stages[stage] = {
105	      ...projection,
106	      status,
107	      finishedAt: timestamp,
108	      error,
109	    };
110	    changed = true;
111	  }
112	  return changed ? { ...task, stages } : task;
113	}
