164	export function applySubagentStatusEvent(
165	  task: TaskProjection,
166	  envelope: EventEnvelope,
167	  payload: Extract<
168	    EventPayload,
169	    | { type: "subagent_started" }
170	    | { type: "subagent_progress" }
171	    | { type: "subagent_completed" }
172	    | { type: "subagent_failed" }
173	    | { type: "subagent_cancelled" }
174	    | { type: "subagent_interrupted" }
175	    | { type: "subagent_input_required" }
176	    | { type: "subagent_input_resumed" }
177	    | { type: "subagent_cancel_requested" }
178	  >,
179	): TaskProjection {
180	  switch (payload.type) {
181	    case "subagent_started":
182	      return upsertSubagent(task, payload.subagent_id, (subagent) => ({
183	        ...subagent,
184	        status: "running",
185	        startedAt: subagent.startedAt ?? envelope.timestamp,
186	      }));
187	    case "subagent_progress":
188	      return upsertSubagent(task, payload.subagent_id, (subagent) => ({
189	        ...subagent,
190	        progressCurrent: payload.current,
191	        progressTotal: payload.total,
192	        progressMessage: payload.message,
193	      }));
194	    case "subagent_completed":
195	    case "subagent_failed":
196	    case "subagent_cancelled":
197	    case "subagent_interrupted":
198	      return upsertSubagent(task, payload.subagent_id, (subagent) => ({
199	        ...subagent,
200	        status: payload.result.status,
201	        finishedAt: envelope.timestamp,
202	        resultSummary: payload.result.summary,
203	        warnings: [...payload.result.warnings],
204	        sourceAssetIds: [...payload.result.source_asset_ids],
205	        recipeId: payload.result.recipe_id,
206	        errorCode: payload.result.error_code,
207	        errorMessage: payload.result.error_message,
208	        pendingRequestId: null,
209	      }));
210	    case "subagent_input_required":
211	      return upsertSubagent(task, payload.subagent_id, (subagent) => ({
212	        ...subagent,
213	        pendingRequestId: payload.request_id,
214	      }));
215	    case "subagent_input_resumed":
216	      return upsertSubagent(task, payload.subagent_id, (subagent) =>
217	        subagent.pendingRequestId === payload.request_id
218	          ? { ...subagent, pendingRequestId: null }
219	          : subagent,
220	      );
221	    case "subagent_cancel_requested":
222	      return upsertSubagent(task, payload.subagent_id, (subagent) => ({
223	        ...subagent,
224	        status: "cancel_requested",
225	        errorMessage: payload.reason,
226	      }));
227	  }
