393	export function applyPublicationCreatedEvent(
394	  task: TaskProjection,
395	  envelope: EventEnvelope,
396	  payload: Extract<EventPayload, { type: "publication_created" }>,
397	): TaskProjection {
398	  // Mirror the backend reducer (raise, don't skip): publication events
399	  // require an envelope run_id and the payload run_id must match it. A
400	  // malformed event must not be silently consumed — skipping would advance
401	  // lastSequence and make it unreplayable on reconnect. A re-delivered
402	  // publication_id is a no-op so duplicate entries never accumulate.
403	  if (envelope.run_id === null) {
404	    throw new Error("publication events require run_id");
405	  }
406	  if (payload.run_id !== envelope.run_id) {
407	    throw new Error("payload run_id must match envelope run_id");
408	  }
409	  if (
410	    task.publications.some(
411	      (publication) => publication.publication_id === payload.publication_id,
412	    )
413	  ) {
414	    return task;
415	  }
416	  const previous = task.currentPublicationId;
417	  const publication: PublicationSummary = {
418	    publication_id: payload.publication_id,
419	    manifest_sha256: payload.manifest_sha256,
420	    supersedes_publication_id: payload.supersedes_publication_id ?? previous,
421	    published_at: payload.published_at,
422	  };
423	  return {
424	    ...task,
425	    currentPublicationId: payload.publication_id,
426	    publications: [...task.publications, publication],
427	  };
428	}
